Lemma stack0_ok_aplace : forall O n l h, aplace O n -> O <= l -> h <= O + n -> stack0_ok (l, h).
Proof.
  intros O n l h (P1 & P2 & P3 & [P4|P4]) Hl Hh; [right| left]; cbn; [| lia].
  pose proof aceil_facts as (AF & _). unfold sh, ALOWSH_LO in *. rewrite ASHADOW_BASE_val. Z.div_mod_to_equations. lia.
Qed.

Lemma awin_aplace : forall O n l h, aplace O n -> O <= l -> h <= O + n -> awin (l, h).
Proof.
  intros O n l h AP Hl Hh. split; [eapply aconst_ok_aplace; eauto| split; [eapply stack0_ok_aplace; eauto|]].
  pose proof (aplace_noshadow _ _ AP). cbn [fst snd]. lia.
Qed.

Lemma wins_hi_aplace : forall O n l h, aplace O n -> O <= l -> h <= O + n -> wins_hi [(l, h)].
Proof.
  intros O n l h (P1 & P2 & P3 & P4) Hl Hh. unfold wins_hi. constructor; [cbn [fst snd]; lia| constructor].
Qed.

