  Lemma fs_chunk_call_pl : forall LF k ff fp m0 m1 m2 O cs slo shi',
    as_RFS H LF m0 -> fresh_frame H LF k ff fp ->
    rw_cells bsegs m1 O cs -> aplace O (Z.of_nat (cells_size cs)) -> fsobj H LF O (Z.of_nat (cells_size cs)) ->
    (O + Z.of_nat (cells_size cs) <= slo \/ shi' <= O) ->
    munch (fs_W5 H slo shi' fp ff k) m1 m2 -> wmono bsegs m1 m2 -> rw_cells bsegs m2 O cs.
  Proof.
    intros LF k ff fp m0 m1 m2 O cs slo shi' RF0 FF OC AP FO SEP MU WM. pose proof (rw_cells_bound _ _ _ _ OC).
    eapply rw_cells_transport; [exact OC| exact MU| exact WM|]. unfold fs_W5.
    exact (fsobj_disjoint_pl _ _ _ _ _ _ _ slo shi' RF0 FO FF AP ltac:(lia) SEP).
  Qed.

  Lemma fs_ro_call_pl : forall LF k ff fp m0 m1 m2 O cs slo shi',
    as_RFS H LF m0 -> fresh_frame H LF k ff fp ->
    ro_cells bsegs m1 O cs -> aplace O (Z.of_nat (cells_size cs)) -> fsobj H LF O (Z.of_nat (cells_size cs)) ->
    (O + Z.of_nat (cells_size cs) <= slo \/ shi' <= O) ->
    munch (fs_W5 H slo shi' fp ff k) m1 m2 -> ro_cells bsegs m2 O cs.
  Proof.
    intros LF k ff fp m0 m1 m2 O cs slo shi' RF0 FF OC AP FO SEP MU. pose proof (ro_cells_bound _ _ _ _ OC).
    eapply ro_cells_transport; [exact OC| exact MU|]. unfold fs_W5.
    exact (fsobj_disjoint_pl _ _ _ _ _ _ _ slo shi' RF0 FO FF AP ltac:(lia) SEP).
  Qed.

  Lemma fs_acc_call_pl : forall LF k ff fp m0 m1 m2 O n slo shi',
    as_RFS H LF m0 -> fresh_frame H LF k ff fp -> aceil <= slo ->
    accessible m1 O n -> aplace O n -> 0 <= n -> fsobj H LF O n ->
