  (* [comment removed for export] *)
  Lemma fs_frame_writes_pl : forall LF k ff fp m m' lo shi W,
    as_RFS H ((k, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi -> fresh_frame H LF k ff fp ->
    munch W m m' -> wmono bsegs m m' ->
    Forall (fun iv : Z * Z => aceil <= fst iv \/ (ff <= fst iv /\ snd iv <= ff + fsz k)
                              \/ (Z.shiftr ff 3 + 2147450880 <= fst iv /\ snd iv <= Z.shiftr ff 3 + 2147450880 + fshn k)
                              \/ (exists O n, fsobj H LF O n /\ aplace O n /\ 0 <= n /\ O <= fst iv /\ snd iv <= O + n)) W ->
