  (* [comment removed for export] *)
  Lemma aplace_of_cobj : forall s LB m LF m1 SP shi O n,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> cobj LB LF SP shi O n -> 0 <= n -> aplace O n.
  Proof.
    intros s LB m LF m1 SP shi O n RH RF [AO|S] Hn.
    - apply aplace_of_aapp; [eapply (aobj_aapp H HH); eauto| exact Hn].
    - pose proof (sobj_facts _ _ _ _ S) as (F1 & F2 & F3 & F4 & F5 & F6 & F7). apply aplace_stack; lia.
  Qed.
  Lemma sep_of_cobj : forall s LB m LF m1 SP shi O n lo,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> cobj LB LF SP shi O n -> aceil <= lo -> O + n <= lo \/ SP <= O.
  Proof. intros. eapply (cobj_off_frame H HH); eauto. lia. Qed.
